describe('Form Submission Success Feedback', () => {
  beforeEach(() => {
    cy.visit('/form');
    cy.get('form').should('be.visible');
  });

  it('should display success message after valid form submission', () => {
    cy.get('input[name="email"]').type('valid.user@example.com');
    cy.get('input[name="password"]').type('SecurePassword123!');
    cy.get('input[name="firstName"]').type('John');
    cy.get('input[name="lastName"]').type('Doe');
    cy.get('input[name="phone"]').type('555-123-4567');
    cy.get('textarea[name="message"]').type('This is a test message');
    cy.get('input[type="checkbox"][name="terms"]').check();

    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');
    cy.get('[data-testid="success-icon"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('have.css', 'color').and('include', 'rgb');
  });

  it('should display success feedback with correct styling and auto-dismiss after timeout', () => {
    cy.get('input[name="email"]').type('another.user@test.com');
    cy.get('input[name="password"]').type('AnotherPass456!');
    cy.get('input[name="firstName"]').type('Jane');
    cy.get('input[name="lastName"]').type('Smith');
    cy.get('input[name="phone"]').type('555-987-6543');
    cy.get('textarea[name="message"]').type('Another test message');
    cy.get('input[type="checkbox"][name="terms"]').check();

    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('have.class', 'success-alert');
    cy.get('[data-testid="success-close-btn"]').should('be.visible');

    cy.get('[data-testid="success-close-btn"]').click();
    cy.get('[data-testid="success-message"]').should('not.be.visible');
  });

  it('should show success feedback with submission details', () => {
    const testEmail = 'detail.test@example.com';
    const testFirstName = 'Robert';

    cy.get('input[name="email"]').type(testEmail);
    cy.get('input[name="password"]').type('DetailPass789!');
    cy.get('input[name="firstName"]').type(testFirstName);
    cy.get('input[name="lastName"]').type('Johnson');
    cy.get('input[name="phone"]').type('555-456-7890');
    cy.get('textarea[name="message"]').type('Detail test message');
    cy.get('input[type="checkbox"][name="terms"]').check();

    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-details"]').should('contain', testEmail);
    cy.get('[data-testid="success-details"]').should('contain', testFirstName);
    cy.get('[data-testid="submission-timestamp"]').should('exist');
  });

  it('should handle rapid successive form submissions with success feedback', () => {
    cy.get('input[name="email"]').type('rapid.test@example.com');
    cy.get('input[name="password"]').type('RapidPass123!');
    cy.get('input[name="firstName"]').type('Alice');
    cy.get('input[name="lastName"]').type('Williams');
    cy.get('input[name="phone"]').type('555-321-0987');
    cy.get('textarea[name="message"]').type('Rapid test message');
    cy.get('input[type="checkbox"][name="terms"]').check();

    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');

    cy.get('[data-testid="success-close-btn"]').click();
    cy.get('[data-testid="success-message"]').should('not.be.visible');

    cy.get('input[name="email"]').clear().type('second.rapid@example.com');
    cy.get('input[name="password"]').clear().type('SecondPass456!');
    cy.get('input[name="firstName"]').clear().type('Bob');
    cy.get('input[name="lastName"]').clear().type('Brown');
    cy.get('input[name="phone"]').clear().type('555-654-3210');
    cy.get('textarea[name="message"]').clear().type('Second rapid message');

    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');
  });
});
